/* Chapter 2 diagnosis cards. Source: Kaplan & Sadock's Synopsis of Psychiatry, 12th ed., Chapter 2. */
KS.add("ch02", "diagnosis", [
  {"id":"d2-id01","tag":"ID","q":"What two deficits define intellectual disability, and by what age must they begin?","a":"Deficits in **intellectual functioning** and in **adaptive functioning**, beginning **before age 18**."},
  {"id":"d2-id02","tag":"ID","q":"How does DSM-5 determine the severity of intellectual disability?","a":"By **adaptive functioning** in conceptual, social and practical domains, not by IQ."},
  {"id":"d2-id03","tag":"ID","q":"Why did DSM-5 move away from IQ for severity?","a":"Adaptive function determines the **support needed**, and IQ scores are **less valid** at the low end of the range."},
  {"id":"d2-id04","tag":"ID","q":"What IQ ranges does ICD-10 use for severity?","a":"Mild **50–69**, moderate **35–49**, severe **20–34**, profound **below 20**."},
  {"id":"d2-id05","tag":"ID","q":"What share of people with intellectual disability have mild disability?","a":"About **85%**."},
  {"id":"d2-id06","tag":"ID","q":"What academic level do people with mild intellectual disability usually reach?","a":"About **sixth grade** by late adolescence."},
  {"id":"d2-id07","tag":"ID","q":"What academic level is typical for moderate intellectual disability?","a":"Rarely above **second to third grade**."},
  {"id":"d2-id08","tag":"ID","q":"What is borderline intellectual functioning in DSM-5?","a":"IQ about 70–80; **not a diagnosis**, only a condition that may be a focus of clinical attention."},
  {"id":"d2-id09","tag":"ID","q":"When is unspecified intellectual disability used?","a":"For children **over 5** who are hard to evaluate (e.g., blind, deaf, severe mental disorder) but probably have intellectual disability."},
  {"id":"d2-id10","tag":"ID","q":"Which scale is commonly used to measure adaptive behavior?","a":"The **Vineland Adaptive Behavior Scale**."},
  {"id":"d2-id11","tag":"Workup","q":"When should chromosome analysis be ordered?","a":"When **multiple physical anomalies, developmental delay and intellectual disability** occur together."},
  {"id":"d2-id12","tag":"Workup","q":"What is the most common known cause of intellectual disability?","a":"**Chromosomal abnormalities**."},
  {"id":"d2-id13","tag":"Workup","q":"Which findings are indications for neuroimaging in intellectual disability?","a":"**Seizures, micro- or macrocephaly, loss of previously acquired skills**, or neurologic signs (dystonia, spasticity, abnormal reflexes)."},
  {"id":"d2-id14","tag":"Workup","q":"Why should hearing be tested in every child evaluated for intellectual disability?","a":"Hearing loss is common in this group and can also **simulate** intellectual disability."},
  {"id":"d2-id15","tag":"Differential","q":"How does a specific learning disorder differ from intellectual disability?","a":"Delay is limited to **one area** (e.g., reading); intellectual disability delays **most** areas."},
  {"id":"d2-id16","tag":"Differential","q":"How do delays from severe neglect differ from intellectual disability?","a":"They are **partly reversible** in an enriched, stimulating environment."},
  {"id":"d2-id17","tag":"Differential","q":"A child under 18 with IQ below 70 meets criteria for dementia. What is diagnosed?","a":"**Both** dementia and intellectual disability; new impairment after 18 is dementia only."},
  {"id":"d2-id18","tag":"Comorbidity","q":"How common are psychiatric disorders in intellectual disability?","a":"Up to **two-thirds**; one study found **40.7%** of 4- to 18-year-olds met criteria for at least one."},
  {"id":"d2-id19","tag":"Comorbidity","q":"Which comorbidities go with mild versus severe intellectual disability?","a":"Mild: **disruptive and conduct** problems. Severe: **autism spectrum disorder**, self-stimulation and self-mutilation."},
  {"id":"d2-id20","tag":"Comorbidity","q":"What proportion of people with ASD have an IQ below 70?","a":"About **70–75%**."},
  {"id":"d2-id21","tag":"Epidemiology","q":"What is the prevalence of intellectual disability and its sex ratio?","a":"About **1–3%** in Western societies; about **1.5 times** more common in males."},
  {"id":"d2-id22","tag":"Epidemiology","q":"At what age does the incidence of intellectual disability peak?","a":"School age, **10–14 years**."},
  {"id":"d2-id23","tag":"Genetics","q":"What are the three chromosomal forms of Down syndrome?","a":"**Trisomy 21** by nondisjunction (most), **mosaicism**, and **translocation** (usually 21;15, often inherited)."},
  {"id":"d2-id24","tag":"Genetics","q":"What are the newborn signs of Down syndrome?","a":"**Hypotonia**, oblique palpebral fissures, excess neck skin, flat skull, protruding tongue, **single palmar crease**, weak or absent Moro reflex."},
  {"id":"d2-id25","tag":"Genetics","q":"What neuropathology appears in Down syndrome after age 40?","a":"**Senile plaques and neurofibrillary tangles** like Alzheimer disease."},
  {"id":"d2-id26","tag":"Genetics","q":"What is the physical phenotype of fragile X syndrome?","a":"**Long face, large ears**, short stature, hyperextensible joints and **postpubertal macroorchidism**."},
  {"id":"d2-id27","tag":"Genetics","q":"Which psychiatric problems are typical of fragile X syndrome?","a":"**ADHD** (up to three-fourths), learning disorders, **autism spectrum** features, social avoidance, perseverative speech."},
  {"id":"d2-id28","tag":"Genetics","q":"What is the hallmark behavior of Prader–Willi syndrome?","a":"**Compulsive eating** (hyperphagia) with obesity."},
  {"id":"d2-id29","tag":"Genetics","q":"Which deletion causes cri-du-chat, and why the cry?","a":"A chromosome **5** deletion; laryngeal anomalies cause a **catlike cry** that fades with age."},
  {"id":"d2-id30","tag":"Genetics","q":"What enzyme is missing in PKU?","a":"**Phenylalanine hydroxylase**, so phenylalanine cannot be converted to tyrosine."},
  {"id":"d2-id31","tag":"Genetics","q":"Describe Rett syndrome.","a":"Girls only; after normal early development, loss of speech and purposeful hand use, **hand-wringing**, slowing head growth, ataxia, **hyperventilation and breath-holding while awake**, seizures, scoliosis."},
  {"id":"d2-id32","tag":"Genetics","q":"What skin findings mark tuberous sclerosis?","a":"**Adenoma sebaceum** and **ash-leaf spots**; seizures and infantile spasms are common."},
  {"id":"d2-id33","tag":"Genetics","q":"What behavior characterizes Lesch–Nyhan syndrome?","a":"Severe compulsive **self-mutilation by biting** the lips and fingers."},
  {"id":"d2-id34","tag":"Genetics","q":"What was childhood disintegrative disorder?","a":"Marked regression after **at least 2 years** of normal development (Heller syndrome); now within autism spectrum disorder."},
  {"id":"d2-id35","tag":"Acquired","q":"Which maternal infection is now the main infectious cause of congenital malformations and intellectual disability?","a":"**Rubella** (replacing syphilis)."},
  {"id":"d2-id36","tag":"Acquired","q":"What are the facial features of fetal alcohol syndrome?","a":"**Short palpebral fissures, smooth or short philtrum, thin upper lip**, midface hypoplasia, epicanthal folds, microcephaly."},
  {"id":"d2-id37","tag":"Acquired","q":"Which congenital infection causes chorioretinitis?","a":"**Toxoplasmosis** (also hydrocephalus, seizures, microcephaly)."},
  {"id":"d2-id38","tag":"Acquired","q":"Which congenital infection is marked by intracerebral calcification and hepatosplenomegaly?","a":"**Cytomegalic inclusion disease**."},
  {"id":"d2-cm01","tag":"Language","q":"What are the four domains of language competence?","a":"**Phonology, grammar, semantics and pragmatics**."},
  {"id":"d2-cm02","tag":"Language","q":"What defines language disorder on testing?","a":"Standardized **expressive or receptive** language scores markedly below **nonverbal IQ** and age expectations."},
  {"id":"d2-cm03","tag":"Language","q":"How do expressive and mixed receptive–expressive deficits differ in comprehension?","a":"Expressive only: comprehension **within normal limits**. Mixed: comprehension **markedly below** age level."},
  {"id":"d2-cm04","tag":"Language","q":"What test does every child with a speech or language disorder need?","a":"An **audiogram** to rule out hearing loss."},
  {"id":"d2-cm05","tag":"Language","q":"How can a child with mixed receptive–expressive deficits be mistaken for deaf?","a":"They respond to **environmental sounds** but not to **spoken language**."},
  {"id":"d2-cm06","tag":"Language","q":"What share of late-talking toddlers catch up in the preschool years?","a":"About **50–80%**."},
  {"id":"d2-cm07","tag":"Language","q":"Which comorbidities are typical of mixed receptive–expressive deficits?","a":"About **half** have speech sound disorder, about **half** reading disorder, and at least **one-third** ADHD."},
  {"id":"d2-cm08","tag":"Language","q":"How does language disorder differ from autism spectrum disorder?","a":"Children with language disorder use gesture and symbolic play and are **motivated to make friends**; ASD impairs social relatedness and play."},
  {"id":"d2-cm09","tag":"Language","q":"What distinguishes acquired aphasia in a child?","a":"**Normal early language** with loss after head trauma or a neurologic disorder such as seizures (Landau–Kleffner)."},
  {"id":"d2-cm10","tag":"Language","q":"What imaging finding is reported in language disorders?","a":"Reduced **left–right asymmetry** in perisylvian and planum temporale regions (sometimes reversed)."},
  {"id":"d2-cm11","tag":"Speech","q":"What excludes a diagnosis of speech sound disorder?","a":"A known **structural or neurologic** cause: cerebral palsy, cleft palate, hearing loss, brain injury."},
  {"id":"d2-cm12","tag":"Speech","q":"Rank speech sound errors by severity.","a":"**Omissions** most severe, then **substitutions**, then **distortions**."},
  {"id":"d2-cm13","tag":"Speech","q":"Which sounds are most often misarticulated?","a":"Late-acquired sounds: **r, sh, th, f, z, l, ch**; vowels are not affected."},
  {"id":"d2-cm14","tag":"Speech","q":"What are the lateral slip and the palatal lisp?","a":"Distortions of s: the lateral slip gives a **whistling** s; the palatal lisp makes s sound like **sh**."},
  {"id":"d2-cm15","tag":"Speech","q":"By when do most children outgrow speech sound disorder, and when is recovery unlikely?","a":"Most by **third grade**; spontaneous recovery is rare after **8 years**."},
  {"id":"d2-cm16","tag":"Speech","q":"Which signs point to dysarthria rather than speech sound disorder?","a":"**Drooling**, slow or uncoordinated movement, abnormal chewing or swallowing, poor tongue movement and slow speech."},
  {"id":"d2-cm17","tag":"Stuttering","q":"What are the core features of stuttering?","a":"Sound or syllable **repetitions, prolongations**, broken words, **blocks** and pauses, often with tension, blinks or grimaces."},
  {"id":"d2-cm18","tag":"Stuttering","q":"When does stuttering usually begin?","a":"Between 18 months and 9 years, with peaks at **2–3½** and **5–7** years; 90% by age 7."},
  {"id":"d2-cm19","tag":"Stuttering","q":"In which situations does stuttering often disappear?","a":"**Singing, reading aloud**, and talking to pets or objects."},
  {"id":"d2-cm20","tag":"Stuttering","q":"Describe phase 4 of stuttering.","a":"Late adolescence and adulthood: **fearful anticipation**, avoidance of words and situations, word substitution and circumlocution."},
  {"id":"d2-cm21","tag":"Stuttering","q":"How is normal preschool dysfluency told from early stuttering?","a":"Normally dysfluent children are **at ease**; stutterers are tense, with part-word repetitions and prolongations."},
  {"id":"d2-cm22","tag":"Stuttering","q":"How does cluttering differ from stuttering?","a":"Cluttering is rapid, jerky, dysrhythmic speech and the speaker is **unaware** of it."},
  {"id":"d2-cm23","tag":"Stuttering","q":"Which psychiatric disorder is common in adults who still stutter?","a":"**Social anxiety disorder**, in about 40–60%."},
  {"id":"d2-cm24","tag":"Pragmatic","q":"What four deficits are required for social (pragmatic) communication disorder?","a":"Social uses of communication (greeting, sharing), **adapting to listener and context**, **conversational rules**, and understanding the **implicit** (inference, humor)."},
  {"id":"d2-cm25","tag":"Pragmatic","q":"When should ASD be diagnosed instead of social (pragmatic) communication disorder?","a":"Whenever restricted, repetitive behaviors are present **now or in the history**."},
  {"id":"d2-cm26","tag":"Pragmatic","q":"How does social anxiety disorder differ from social (pragmatic) communication disorder?","a":"In social anxiety the skills **exist** but are not used in feared settings; in pragmatic disorder they are **absent in every setting**."},
  {"id":"d2-cm27","tag":"Pragmatic","q":"At what age is social (pragmatic) communication disorder usually diagnosable?","a":"Rarely **before 4**; mild cases may not show until **adolescence**."},
  {"id":"d2-as01","tag":"ASD","q":"What are the two core symptom domains of autism spectrum disorder in DSM-5?","a":"Deficits in **social communication and interaction**, and **restricted, repetitive** behaviors, interests or activities."},
  {"id":"d2-as02","tag":"ASD","q":"Is abnormal language a core criterion for autism spectrum disorder?","a":"**No**: it is an associated feature, captured by a 'with or without language impairment' specifier."},
  {"id":"d2-as03","tag":"ASD","q":"Which DSM-IV disorders were merged into autism spectrum disorder?","a":"**Autistic disorder, Asperger disorder, childhood disintegrative disorder, Rett syndrome and PDD-NOS**."},
  {"id":"d2-as04","tag":"ASD","q":"What were the average ages at diagnosis for the former subtypes?","a":"Autistic disorder **3.1 years**, PDD-NOS 3.9, Asperger **7.2**."},
  {"id":"d2-as05","tag":"ASD","q":"In what share of children with ASD is early language lost?","a":"Up to **25%**."},
  {"id":"d2-as06","tag":"ASD","q":"What are the DSM-5 specifiers for autism spectrum disorder?","a":"Severity of each domain; with or without **intellectual impairment**; with or without **language impairment**; associated conditions; **with catatonia**."},
  {"id":"d2-as07","tag":"ASD","q":"What is theory of mind, and how is it affected in ASD?","a":"The ability to attribute feelings and intentions to others (and oneself); **impaired** in ASD, limiting empathy and reciprocity."},
  {"id":"d2-as08","tag":"ASD","q":"Describe attachment in children with ASD.","a":"Atypical but **not absent**; they may not differentiate important people or react to being left with a stranger."},
  {"id":"d2-as09","tag":"ASD","q":"What is pronoun reversal?","a":"Using the wrong pronoun, e.g., saying **\"You want the toy\"** meaning \"I want the toy\"; often with echolalia."},
  {"id":"d2-as10","tag":"ASD","q":"What is hyperlexia?","a":"Early, fluent **reading** with little **comprehension** of what is read."},
  {"id":"d2-as11","tag":"ASD","q":"What is the typical IQ profile in ASD?","a":"**Performance (visuospatial, rote memory) higher than verbal**; weakest in verbal sequencing and abstraction."},
  {"id":"d2-as12","tag":"ASD","q":"How common is insomnia in school-age children with ASD?","a":"About **44–83%**."},
  {"id":"d2-as13","tag":"ASD","q":"Which standardized instrument helps diagnose autism spectrum disorder?","a":"The **Autism Diagnostic Observation Schedule (ADOS-G)**."},
  {"id":"d2-as14","tag":"Differential","q":"How do deaf infants differ from infants with ASD in babbling and response to sound?","a":"Deaf infants **babble normally then stop** at 6–12 months and respond only to loud sounds; children with ASD may ignore loud sounds but attend to soft ones."},
  {"id":"d2-as15","tag":"Differential","q":"How does childhood-onset schizophrenia differ from ASD?","a":"Onset rarely before 12 (almost never before 5), **hallucinations and delusions**, deterioration from prior functioning, fewer seizures and less intellectual disability."},
  {"id":"d2-as16","tag":"Differential","q":"How does intellectual disability differ from ASD?","a":"Intellectual disability is **globally even**; ASD shows social relating **weaker** than other abilities."},
  {"id":"d2-as17","tag":"Differential","q":"How does psychosocial deprivation differ from ASD?","a":"Deprived children **improve** in an enriched environment; children with ASD do not."},
  {"id":"d2-as18","tag":"Differential","q":"Name three features that favor language disorder over ASD.","a":"Active use of **gestures**, intact **imaginative play**, frequent **articulation problems** (and near-equal sex ratio)."},
  {"id":"d2-as19","tag":"Prognosis","q":"Which children with ASD have the best prognosis?","a":"Those with **IQ above 70**, average adaptive skills and **communicative language by 5–7 years**."},
  {"id":"d2-as20","tag":"Prognosis","q":"Which ASD symptoms respond least to early behavioral treatment?","a":"**Ritualistic and repetitive** behaviors."},
  {"id":"d2-as21","tag":"Epidemiology","q":"What is the current US prevalence and sex ratio of ASD?","a":"About **1 in 54** children; **4:1** male."},
  {"id":"d2-as22","tag":"Epidemiology","q":"Why might girls diagnosed with ASD more often have intellectual disability?","a":"Girls without intellectual disability may be **missed**, less often referred and diagnosed."},
  {"id":"d2-as23","tag":"Neurology","q":"How often do people with ASD have grand mal seizures?","a":"About **4–32%** at some time."},
  {"id":"d2-ad01","tag":"ADHD","q":"What are the DSM-5 symptom count, duration and onset rules for ADHD?","a":"At least **6** symptoms in a domain (**5** from age 17), for **6 months**, with several present **before 12**, in **two or more settings**."},
  {"id":"d2-ad02","tag":"ADHD","q":"What replaced ADHD subtypes in DSM-5?","a":"Three presentations: **combined, predominantly inattentive, predominantly hyperactive/impulsive**."},
  {"id":"d2-ad03","tag":"ADHD","q":"Can ADHD be diagnosed with autism spectrum disorder in DSM-5?","a":"**Yes**: DSM-5 permits the comorbid diagnosis."},
  {"id":"d2-ad04","tag":"ADHD","q":"Which ADHD presentations are more stable and more often comorbid with conduct disorder?","a":"**Combined** and **hyperactive-impulsive** presentations."},
  {"id":"d2-ad05","tag":"ADHD","q":"What does the mental status examination usually show in ADHD?","a":"Possible demoralization, distractibility, perseveration; **no thought disorder** or impaired reality testing."},
  {"id":"d2-ad06","tag":"ADHD","q":"Which medical conditions can mimic ADHD?","a":"**Absence seizures**, hearing or visual impairment, **thyroid** disease, hypoglycemia, a temporal lobe seizure focus."},
  {"id":"d2-ad07","tag":"ADHD","q":"What cardiac history matters before ADHD treatment?","a":"**Syncope**, **family history of sudden death**, and the cardiac examination; cardiology consultation if risk factors exist."},
  {"id":"d2-ad08","tag":"ADHD","q":"What errors on a continuous performance task reflect inattention versus impulsivity?","a":"Inattention: **omission** errors. Impulsivity: **commission** errors."},
  {"id":"d2-ad09","tag":"ADHD","q":"How is mania told from ADHD in children?","a":"Mania's symptoms **wax and wane** (episodic); ADHD is persistent. Both share talkativeness, hyperactivity and distractibility."},
  {"id":"d2-ad10","tag":"ADHD","q":"Which ADHD symptom usually remits first and which last?","a":"**Overactivity** first; **distractibility** last."},
  {"id":"d2-ad11","tag":"ADHD","q":"What predicts persistence of ADHD?","a":"**Family history**, adverse life events, and comorbid conduct, depressive and anxiety symptoms."},
  {"id":"d2-ad12","tag":"ADHD","q":"When does ADHD remission usually occur?","a":"Between about **12 and 20**; rarely in middle childhood."},
  {"id":"d2-ad13","tag":"ADHD","q":"Is the substance use risk in ADHD due mainly to ADHD itself?","a":"**No**: it relates more to comorbid **conduct disorder**."},
  {"id":"d2-ad14","tag":"ADHD","q":"What are the prevalence and sex ratio of ADHD?","a":"About **5–8%** of school-age children (7–8% prepubertal); boys **2:1 to 9:1**; about 2.5–4% of adults."},
  {"id":"d2-ad15","tag":"ADHD","q":"What is the heritability of ADHD?","a":"About **75%**; first-degree relatives have 2–8 times the risk."},
  {"id":"d2-ad16","tag":"ADHD","q":"What are the Utah criteria for adult ADHD?","a":"Retrospective childhood ADHD, ongoing **inattention and hyperactivity** plus at least three of mood lability, hot temper, poor stress tolerance, disorganization, impulsivity; excludes severe depression, psychosis, severe personality disorder."},
  {"id":"d2-ad17","tag":"ADHD","q":"How does the presentation of ADHD shift into adulthood?","a":"Many move from combined to **predominantly inattentive** as hyperactivity fades."},
  {"id":"d2-ad18","tag":"ADHD","q":"In an adult with attention problems, what favors ADHD over a bipolar spectrum disorder?","a":"**Lifelong** rather than episodic symptoms, with chronic school problems in childhood."},
  {"id":"d2-ld01","tag":"SLD","q":"What did DSM-5 change about learning disorders?","a":"Merged reading, math and written expression disorders into **specific learning disorder** with specifiers, and dropped the **IQ-discrepancy** criterion."},
  {"id":"d2-ld02","tag":"SLD","q":"What must be excluded before diagnosing specific learning disorder?","a":"Intellectual disability, visual or hearing impairment, another disorder, psychosocial adversity and **inadequate education**."},
  {"id":"d2-ld03","tag":"SLD","q":"How common is specific learning disorder?","a":"About **10%** of youth; boys **2–3:1**."},
  {"id":"d2-ld04","tag":"SLD","q":"What share of children with specific learning disorder have reading impairment?","a":"Up to **75%**."},
  {"id":"d2-ld05","tag":"Reading","q":"What is the core cognitive deficit in most reading disorders?","a":"Poor processing of **speech sounds (phonemes)**, so children cannot sound out words."},
  {"id":"d2-ld06","tag":"Reading","q":"When is reading impairment usually identified?","a":"By about **7 (second grade)**; bright children may compensate until **9 (fourth grade)**."},
  {"id":"d2-ld07","tag":"Reading","q":"What oral reading errors are typical in dyslexia?","a":"**Omissions, additions and distortions** of words; confusing letters that differ in orientation."},
  {"id":"d2-ld08","tag":"Reading","q":"Can children with reading disorder copy text and spell?","a":"Most **copy** at age level, but nearly all **spell poorly**."},
  {"id":"d2-ld09","tag":"Reading","q":"How is reading disorder distinguished from ADHD alone?","a":"Reading disorder involves **linguistic** deficits; ADHD alone does not."},
  {"id":"d2-ld10","tag":"Reading","q":"How is poor reading from inadequate schooling detected?","a":"By comparing the child's standardized reading scores with **classmates**."},
  {"id":"d2-ld11","tag":"Reading","q":"Which theories of dyslexia are myths?","a":"**Visual-motor problems (scotopic sensitivity), allergies** and cerebellar-vestibular causes."},
  {"id":"d2-ld12","tag":"Reading","q":"What brain finding is linked with reading and language disorders?","a":"Less **asymmetry of the left planum temporale**."},
  {"id":"d2-ld13","tag":"Math","q":"What are the four skill groups impaired in mathematics disorder?","a":"**Linguistic, perceptual, mathematical and attentional** skills."},
  {"id":"d2-ld14","tag":"Math","q":"When is math impairment usually identified?","a":"By about **8 (second to third grade)**, sometimes as early as 6 or as late as 10."},
  {"id":"d2-ld15","tag":"Math","q":"Which test assesses math skills in grades 1–6?","a":"The **KeyMath Diagnostic Arithmetic Test**."},
  {"id":"d2-ld16","tag":"Writing","q":"What are the main features of impaired written expression?","a":"**Spelling** errors (often phonetic), grammar and punctuation errors, poor paragraph organization and poor handwriting."},
  {"id":"d2-ld17","tag":"Writing","q":"Which tests assess written expression?","a":"The **Test of Written Language (TOWL)**, DEWS and TEWL."},
  {"id":"d2-ld18","tag":"Writing","q":"What should be ruled out when a child produces little writing?","a":"**ADHD or depression** interfering with focus; treating them should improve writing."},
  {"id":"d2-ld19","tag":"Writing","q":"What is the prevalence of impaired written expression?","a":"About **5–15%** of school-age children; boys 2–3:1."},
  {"id":"d2-mo01","tag":"DCD","q":"What defines developmental coordination disorder?","a":"Motor coordination well **below age and intellect**, impairing daily life, play or school, **not** due to a neurologic or neuromuscular condition."},
  {"id":"d2-mo02","tag":"DCD","q":"How common is developmental coordination disorder and what is its main comorbidity?","a":"About **5–6%** of school-age children; about **half** have ADHD or dyslexia."},
  {"id":"d2-mo03","tag":"DCD","q":"Which test measures agility and coordination in DCD?","a":"The **Bruininks-Oseretsky** Test of Motor Development."},
  {"id":"d2-mo04","tag":"DCD","q":"Does a mildly clumsy child qualify for DCD?","a":"**No**, not unless functioning is impaired."},
  {"id":"d2-mo05","tag":"DCD","q":"Does DCD usually resolve with age?","a":"**No**: clumsiness often persists into adolescence and adulthood, with risks of low self-esteem and obesity."},
  {"id":"d2-mo06","tag":"DCD","q":"Which brain structure is most implicated in DCD?","a":"The **cerebellum** (automatization and internal-modeling deficit hypotheses)."},
  {"id":"d2-mo07","tag":"Stereotypic","q":"What are the specifiers of stereotypic movement disorder?","a":"**With or without self-injurious behavior**; associated medical, genetic, neurodevelopmental or environmental condition; mild, moderate or severe."},
  {"id":"d2-mo08","tag":"Stereotypic","q":"List five features that distinguish stereotypies from tics.","a":"Earlier onset, **fixed** location, **no premonitory urge**, longer and more **rhythmic**, **self-soothing** (and weaker drug response)."},
  {"id":"d2-mo09","tag":"Stereotypic","q":"When does head banging usually begin?","a":"Between **6 and 12 months**."},
  {"id":"d2-mo10","tag":"Stereotypic","q":"How common are stereotypies in intellectual disability?","a":"About **10–20%**, more with greater severity; self-injury in 2–3%."},
  {"id":"d2-mo11","tag":"Tourette","q":"What are the DSM-5 criteria for Tourette disorder?","a":"**Multiple motor** tics and **at least one vocal** tic (not necessarily concurrent), **more than 1 year** since onset, beginning **before 18**."},
  {"id":"d2-mo12","tag":"Tourette","q":"What is a premonitory urge?","a":"An uncomfortable internal sensation preceding a tic that the tic temporarily **relieves**, reinforcing it."},
  {"id":"d2-mo13","tag":"Tourette","q":"What are the typical ages of tic onset and peak severity?","a":"Onset about **4–6 years**; peak **10–12 years**."},
  {"id":"d2-mo14","tag":"Tourette","q":"What is the most common first tic?","a":"An **eye-blink** tic, followed by head tics or grimaces."},
  {"id":"d2-mo15","tag":"Tourette","q":"How common is coprolalia in Tourette disorder?","a":"In **under 10%**, rarely without comorbid psychiatric disturbance."},
  {"id":"d2-mo16","tag":"Tourette","q":"Define palilalia, echolalia, echopraxia and copropraxia.","a":"Repeating **one's own** words; repeating **others'** words; imitating others' **actions**; making **obscene gestures**."},
  {"id":"d2-mo17","tag":"Tourette","q":"Which obsessive-compulsive symptoms are typical in Tourette disorder?","a":"**Ordering and symmetry, counting and repetitive touching** (rather than contamination or harm)."},
  {"id":"d2-mo18","tag":"Tourette","q":"How often do ADHD and OCD accompany Tourette disorder?","a":"ADHD in **more than half**; OCD in **20–40%**."},
  {"id":"d2-mo19","tag":"Tourette","q":"What happens to tics with age?","a":"**Half to two-thirds** improve markedly or remit by adolescence or early adulthood."},
  {"id":"d2-mo20","tag":"Tourette","q":"Which rating scale is the clinician gold standard for tic severity?","a":"The **Yale Global Tic Severity Scale**."},
  {"id":"d2-mo21","tag":"Chronic tic","q":"What defines persistent (chronic) motor or vocal tic disorder?","a":"**Motor or vocal** tics but **not both**, for more than 1 year, onset before 18, and never Tourette criteria."},
  {"id":"d2-mo22","tag":"Chronic tic","q":"Which children with chronic tics have the best outcome?","a":"Those with onset at **6–8 years** and only **facial** tics; symptoms usually last 4–6 years."},
  {"id":"d2-fe01","tag":"Pica","q":"What are the DSM-5 requirements for pica?","a":"Persistent eating of **nonnutritive, nonfood** substances, developmentally inappropriate (minimum age about **2**), **not culturally sanctioned**, severe enough for clinical attention."},
  {"id":"d2-fe02","tag":"Pica","q":"What complication follows eating paint chips?","a":"**Lead poisoning**."},
  {"id":"d2-fe03","tag":"Pica","q":"Which deficiencies are associated with eating clay and starch?","a":"Clay (geophagia): anemia and **zinc** deficiency; starch (amylophagia): severe **iron** deficiency."},
  {"id":"d2-fe04","tag":"Pica","q":"Which labs should be checked in pica?","a":"**Lead**, hemoglobin, serum **iron and zinc**."},
  {"id":"d2-fe05","tag":"Pica","q":"What is psychosocial dwarfism?","a":"A reversible endocrine and behavioral form of **failure to thrive**, with bizarre eating such as garbage or toilet water."},
  {"id":"d2-fe06","tag":"Pica","q":"What is the prognosis of pica in children of normal intelligence?","a":"Usually **remits within months**; can persist with ASD or intellectual disability."},
  {"id":"d2-fe07","tag":"Rumination","q":"What defines rumination disorder?","a":"Repeated **regurgitation**, re-chewing and re-swallowing or spitting out of food for at least **1 month** after normal functioning, not due to a GI or medical cause."},
  {"id":"d2-fe08","tag":"Rumination","q":"How does an infant look while ruminating?","a":"**Back arched, head back**, rhythmic tongue sucking, apparently **pleased**, no nausea or retching."},
  {"id":"d2-fe09","tag":"Rumination","q":"Is failure to thrive required for rumination disorder?","a":"**No**; it may be a consequence, but infants can be normal weight."},
  {"id":"d2-fe10","tag":"Rumination","q":"How is pyloric stenosis distinguished from rumination?","a":"**Projectile vomiting**, usually evident before **3 months**."},
  {"id":"d2-fe11","tag":"ARFID","q":"What are the three reasons for food avoidance in ARFID?","a":"**Lack of interest** in eating, aversion to **sensory features**, or concern about **consequences** of eating (e.g., choking, vomiting)."},
  {"id":"d2-fe12","tag":"ARFID","q":"What consequences must be present for ARFID?","a":"One or more: **weight loss** or faltering growth, nutritional **deficiency**, dependence on **enteral feeding or supplements**, or psychosocial interference."},
  {"id":"d2-fe13","tag":"ARFID","q":"When is ARFID not diagnosed?","a":"During **anorexia or bulimia nervosa**, when another medical or mental condition explains it, or when food is unavailable."},
  {"id":"d2-tr01","tag":"Attachment","q":"What are the core features of reactive attachment disorder?","a":"A consistently **emotionally withdrawn** pattern toward caregivers: rarely seeks or responds to comfort, limited positive affect, unexplained fear or sadness, after **grossly insufficient care**."},
  {"id":"d2-tr02","tag":"Attachment","q":"What are the core features of disinhibited social engagement disorder?","a":"**Overly familiar** behavior with unfamiliar adults, little hesitation, little checking back with caregivers, willingness to **go off with strangers**, after insufficient care."},
  {"id":"d2-tr03","tag":"Attachment","q":"What age requirements apply to RAD and DSED?","a":"Developmental age of at least **9 months** and evidence of disturbance **before age 5**."},
  {"id":"d2-tr04","tag":"Attachment","q":"What attachment patterns does the strange situation identify?","a":"**Secure, insecure and disorganized** (Mary Ainsworth)."},
  {"id":"d2-tr05","tag":"Attachment","q":"What is disorganized attachment?","a":"The child both **needs closeness** to and is **apprehensive** about approaching the caregiver."},
  {"id":"d2-tr06","tag":"Attachment","q":"What are the physical findings of nonorganic failure to thrive with RAD?","a":"Weight **below the 3rd percentile**, normal head circumference, weak tone, cool pale skin, delayed bone age, protruding abdomen; **growth hormone normal or raised**."},
  {"id":"d2-tr07","tag":"Attachment","q":"How do children with ASD differ physically from children with RAD?","a":"Children with ASD are usually **well nourished**, of normal size, alert and active."},
  {"id":"d2-tr08","tag":"Attachment","q":"Which attachment disorder has the better course after adoption?","a":"**RAD** improves and may normalize; DSED attachments form less readily."},
  {"id":"d2-tr09","tag":"PTSD","q":"How does reexperiencing appear in young children with PTSD?","a":"**Posttraumatic play** reenacting the event, frightening dreams, and sometimes inappropriate sexual behavior."},
  {"id":"d2-tr10","tag":"PTSD","q":"How do negative changes in mood and cognition appear in children under 6?","a":"**Social withdrawal**, fewer positive emotions, **reduced interest in play**, shame, fear and confusion."},
  {"id":"d2-tr11","tag":"PTSD","q":"Distinguish acute stress disorder, PTSD and delayed expression by timing.","a":"Acute stress disorder: **3 days to 1 month**. PTSD: **more than 1 month**. Delayed expression: full criteria only **6 months** or more after the event."},
  {"id":"d2-tr12","tag":"PTSD","q":"What are the dissociative specifiers of PTSD?","a":"**Depersonalization** (detached from oneself) or **derealization** (world feels unreal)."},
  {"id":"d2-tr13","tag":"PTSD","q":"What does a 'foreshortened future' mean in adolescent PTSD?","a":"The expectation of **dying young**."},
  {"id":"d2-tr14","tag":"PTSD","q":"What long-term brain and cognitive findings accompany severe childhood PTSD?","a":"Smaller **intracranial volume and corpus callosum**, memory deficits and **lower IQ**."},
  {"id":"d2-tr15","tag":"PTSD","q":"Which factors raise a child's risk of PTSD after trauma?","a":"Preexisting **anxiety or depression**, early externalizing problems, lower IQ, negative parental reactions, lack of support, **maternal depression**."},
  {"id":"d2-dp01","tag":"Depression","q":"How does DSM-5 adjust major depression criteria for youth?","a":"**Irritable mood** may replace depressed mood (otherwise adult criteria)."},
  {"id":"d2-dp02","tag":"Depression","q":"Which depressive features are more typical of prepubertal children?","a":"**Somatic complaints**, psychomotor **agitation** and **mood-congruent hallucinations**."},
  {"id":"d2-dp03","tag":"Depression","q":"Which features are more typical of adolescent depression?","a":"**Anhedonia, hopelessness, psychomotor retardation, delusions**, plus negativism, antisocial behavior and substance use."},
  {"id":"d2-dp04","tag":"Depression","q":"Which depressive symptoms occur equally at all ages?","a":"**Suicidal ideation, depressed or irritable mood, insomnia** and poor concentration."},
  {"id":"d2-dp05","tag":"Depression","q":"How do depressive hallucinations usually sound in youth?","a":"A **single voice** from outside the head with **derogatory or suicidal** content (not conversing or commenting voices)."},
  {"id":"d2-dp06","tag":"Depression","q":"What CDRS-R scores mark moderate and significant depression?","a":"**40** moderate; **45 or higher** significant."},
  {"id":"d2-dp07","tag":"Depression","q":"What are the duration and mood criteria for persistent depressive disorder in youth?","a":"Depressed **or irritable** mood most days for at least **1 year**, never symptom-free over 2 months."},
  {"id":"d2-dp08","tag":"Depression","q":"What is double depression?","a":"A **major depressive episode** on top of **persistent depressive disorder**."},
  {"id":"d2-dp09","tag":"Depression","q":"Which features suggest major depression rather than normal bereavement?","a":"Guilt beyond the death, **morbid worthlessness**, death preoccupation beyond joining the deceased, **marked retardation**, prolonged impairment, hallucinations beyond the deceased's voice."},
  {"id":"d2-dp10","tag":"Depression","q":"What happens to school problems caused by depression?","a":"They **correct rapidly** after recovery; don't mistake them for a learning disorder."},
  {"id":"d2-dp11","tag":"Depression","q":"How long does an untreated youth depressive episode last?","a":"About **8–12 months**."},
  {"id":"d2-dp12","tag":"Depression","q":"What are recurrence rates of youth depression?","a":"**20–60%** within 2 years and **70%** by 5 years; highest relapse risk 6–12 months after stopping treatment."},
  {"id":"d2-dp13","tag":"Depression","q":"Which features of youth depression predict later bipolar I disorder?","a":"**Psychotic features, psychomotor retardation, family history of bipolar illness**."},
  {"id":"d2-dp14","tag":"Depression","q":"How does agitation in prepubertal depression usually look?","a":"Inability to sit still, **irritability and tantrums** rather than hand-wringing or pacing (can mimic ADHD)."},
  {"id":"d2-dp15","tag":"Suicide","q":"What is the leading method of youth suicide?","a":"**Firearms**: about two-thirds of boys and half of girls."},
  {"id":"d2-dp16","tag":"Suicide","q":"How do suicide completion and attempt rates differ by sex in adolescents?","a":"Boys **complete** about 5 times more; girls **attempt** at least 3 times more."},
  {"id":"d2-dp17","tag":"Suicide","q":"Which adolescents need hospitalization after suicidal behavior?","a":"Prior (especially lethal) attempts, **males over 12 with aggression or substance abuse**, lethal methods, severe depression with withdrawal, hopelessness and persistent ideation."},
  {"id":"d2-dp18","tag":"Suicide","q":"What is Werther syndrome?","a":"Imitation of highly publicized suicides by vulnerable young people (after Goethe's **The Sorrows of Young Werther**)."},
  {"id":"d2-dp19","tag":"Suicide","q":"What precipitates suicide in younger adolescent completers?","a":"**Impending disciplinary action**, impulsive behavior and **access to loaded guns** at home."},
  {"id":"d2-dp20","tag":"Suicide","q":"Which family factor has the largest association with suicidal behavior?","a":"**Sexual abuse** (within maltreatment generally)."},
  {"id":"d2-bp01","tag":"Bipolar","q":"Which criteria does DSM-5 use for bipolar disorder in children?","a":"The **same criteria as adults**."},
  {"id":"d2-bp02","tag":"Bipolar","q":"How does adolescent mania typically present?","a":"Often after a depressive episode, with **grandiose and paranoid delusions**, hallucinations, flight of ideas and poor reality testing."},
  {"id":"d2-bp03","tag":"Bipolar","q":"Distinguish the narrow and broad phenotypes of pediatric bipolar disorder.","a":"Narrow: **discrete manic/hypomanic episodes**, family bipolar history. Broad: **chronic, nonepisodic irritability**, no increased family bipolar history, leads to depression and anxiety."},
  {"id":"d2-bp04","tag":"Bipolar","q":"How common is ADHD in early-onset bipolar disorder?","a":"Up to **90%** of prepubertal and **50%** of adolescent cases."},
  {"id":"d2-bp05","tag":"Bipolar","q":"Which depressed adolescents are at highest risk of bipolar I?","a":"Those with a **family history of bipolar I** and acute severe depression with **psychosis, hypersomnia and psychomotor retardation**."},
  {"id":"d2-bp06","tag":"Bipolar","q":"What is the course of pediatric bipolar disorder over 2 years?","a":"About **70%** recover from the index episode; half recur, more often **depression** than mania; frequent polarity changes."},
  {"id":"d2-bp07","tag":"Bipolar","q":"Why is bipolar II considered unstable in youth?","a":"About **20%** convert to bipolar I during follow-up."},
  {"id":"d2-bp08","tag":"Bipolar","q":"What features does very early-onset bipolar disorder show?","a":"Lower recovery, more **mixed states, rapid cycling** and polarity changes."},
  {"id":"d2-bp09","tag":"Bipolar","q":"How prevalent is narrow-definition bipolar I in 16-year-olds?","a":"About **0.06–0.1%**."},
  {"id":"d2-dm01","tag":"DMDD","q":"What are the DSM-5 criteria for disruptive mood dysregulation disorder?","a":"Severe outbursts **≥3 times/week**, persistently **irritable mood** between them, for **≥12 months** in **≥2 settings**, onset **before 10**, diagnosed only from **6 to 18**."},
  {"id":"d2-dm02","tag":"DMDD","q":"How is DMDD distinguished from bipolar disorder?","a":"DMDD irritability is **chronic and nonepisodic**; mania is episodic. Bipolar disorder takes precedence."},
  {"id":"d2-dm03","tag":"DMDD","q":"How is DMDD distinguished from ODD?","a":"ODD includes **defiance and annoying** behavior and may occur in **one setting**; DMDD needs two settings and persistent irritable mood. They cannot both be diagnosed."},
  {"id":"d2-dm04","tag":"DMDD","q":"What are the most common comorbidities of DMDD?","a":"**ADHD 94%**, ODD 84%, anxiety 47%, major depression 20%."},
  {"id":"d2-dm05","tag":"DMDD","q":"What do children with DMDD usually develop later?","a":"**Major depression, dysthymia and anxiety disorders**, not bipolar disorder."},
  {"id":"d2-dc01","tag":"ODD","q":"What are the DSM-5 symptom groups of ODD?","a":"**Angry/irritable mood**, **argumentative/defiant behavior**, and **vindictiveness**; at least 4 symptoms for 6 months."},
  {"id":"d2-dc02","tag":"ODD","q":"How often must ODD symptoms occur?","a":"Most days under age 5; at least **once a week** from age 5 (spitefulness at least twice in 6 months)."},
  {"id":"d2-dc03","tag":"ODD","q":"How is ODD severity rated?","a":"By settings: **mild** one, moderate two, severe three or more."},
  {"id":"d2-dc04","tag":"ODD","q":"Why might a child with ODD seem fine in the clinic?","a":"Symptoms appear mainly with **familiar** adults and peers, especially at **home**."},
  {"id":"d2-dc05","tag":"ODD","q":"What is the key distinction between ODD and conduct disorder?","a":"Conduct disorder **violates the basic rights of others**; ODD's hostility and negativism fall short of that."},
  {"id":"d2-dc06","tag":"ODD","q":"Which ODD type tends to progress to conduct disorder?","a":"The **aggressive** forms: angry/irritable and **vindictive** types (and ADHD plus ODD)."},
  {"id":"d2-dc07","tag":"ODD","q":"Which ODD symptom best predicts later psychiatric disorder?","a":"**Irritability** (other features look more like temperament)."},
  {"id":"d2-dc08","tag":"CD","q":"What are the DSM-5 duration rules for conduct disorder?","a":"**3 or more** of 15 criteria in the past **12 months**, with at least one in the past **6 months**."},
  {"id":"d2-dc09","tag":"CD","q":"Which conduct disorder rule violations require onset before 13?","a":"**Staying out at night** despite prohibition and **truancy** from school."},
  {"id":"d2-dc10","tag":"CD","q":"What defines childhood-onset versus adolescent-onset conduct disorder?","a":"Childhood-onset: at least one symptom **before age 10**; adolescent-onset: none before 10."},
  {"id":"d2-dc11","tag":"CD","q":"What is the 'with limited prosocial emotions' specifier?","a":"At least two of: **no remorse or guilt, callous lack of empathy, unconcerned about performance, shallow affect**."},
  {"id":"d2-dc12","tag":"CD","q":"When can conduct disorder be diagnosed after age 18?","a":"Only if criteria for **antisocial personality disorder** are not met."},
  {"id":"d2-dc13","tag":"CD","q":"At what ages do boys and girls usually meet criteria for conduct disorder?","a":"Boys **10–12**, girls **14–16**."},
  {"id":"d2-dc14","tag":"CD","q":"What are poor prognostic signs in conduct disorder?","a":"**Young age at onset, many symptoms, severe symptoms**."},
  {"id":"d2-dc15","tag":"CD","q":"What predicts later incarceration better than a CD diagnosis?","a":"**Assaultive behavior** in childhood and **parental criminality**."},
  {"id":"d2-dc16","tag":"CD","q":"What is the prevalence and sex ratio of conduct disorder?","a":"Males **6–16%**, females 2–9%; ratio **4:1 to 12:1**."},
  {"id":"d2-ax01","tag":"Anxiety","q":"What are the duration requirements for separation anxiety disorder?","a":"At least **4 weeks** in children and adolescents (6 months in adults), with **3 or more** symptoms."},
  {"id":"d2-ax02","tag":"Anxiety","q":"List four symptoms of separation anxiety disorder.","a":"Worry about **harm to or losing** attachment figures, **school refusal**, refusal to **sleep apart**, separation **nightmares**, physical complaints when separation looms."},
  {"id":"d2-ax03","tag":"Anxiety","q":"When does normal separation anxiety peak and fade?","a":"Peaks at **9–18 months** and fades by about **2½ years**."},
  {"id":"d2-ax04","tag":"Anxiety","q":"What extra requirement applies to social anxiety disorder in children?","a":"Anxiety must occur in **peer** settings, not only with adults."},
  {"id":"d2-ax05","tag":"Anxiety","q":"How might social anxiety show in young children?","a":"**Crying, tantrums, freezing**, clinging or not speaking in social situations."},
  {"id":"d2-ax06","tag":"Anxiety","q":"Which is the most common anxiety disorder in youth?","a":"**Generalized anxiety disorder**, more common in adolescents."},
  {"id":"d2-ax07","tag":"Anxiety","q":"What is behavioral inhibition and its physiologic correlates?","a":"Shyness and withdrawal with the unfamiliar (~15% of young children); **higher resting heart rate**, higher morning **cortisol**, low heart rate variability."},
  {"id":"d2-ax08","tag":"Anxiety","q":"How does panic disorder with agoraphobia differ from separation anxiety?","a":"Uncommon before 18; fear of being **incapacitated by panic**, not of separation."},
  {"id":"d2-ax09","tag":"Anxiety","q":"Is school refusal pathognomonic of separation anxiety disorder?","a":"**No**: it also occurs with phobias, social anxiety, performance fears and learning disorders."},
  {"id":"d2-ax10","tag":"Anxiety","q":"What predicted remission in CAMS?","a":"**Younger age**, lower severity, no comorbid depression or anxiety, and **social anxiety not** the primary disorder."},
  {"id":"d2-ax11","tag":"Mutism","q":"What are the DSM-5 criteria for selective mutism?","a":"Consistent failure to speak where speech is expected (e.g., school) despite speaking elsewhere, for **≥1 month** (not the first month of school), causing impairment, not due to a communication disorder or unfamiliar language."},
  {"id":"d2-ax12","tag":"Mutism","q":"How does selective mutism differ from communication disorders and ASD?","a":"Children with selective mutism **can** speak normally when comfortable; the others reflect **inability**."},
  {"id":"d2-ax13","tag":"Mutism","q":"When is selective mutism diagnosed in a child learning a new language?","a":"Only if the child also refuses the **native language** or is competent in the new language but will not speak it."},
  {"id":"d2-ax14","tag":"Mutism","q":"Which disorder is most closely related to selective mutism?","a":"**Social anxiety disorder** (90% met criteria in one survey)."},
  {"id":"d2-ax15","tag":"Mutism","q":"What predicts a poor prognosis in selective mutism?","a":"Failure to improve **by age 10**."},
  {"id":"d2-oc01","tag":"OCD","q":"How does pediatric OCD differ from adult OCD in insight?","a":"Youth more often **do not regard** their obsessions or rituals as unreasonable."},
  {"id":"d2-oc02","tag":"OCD","q":"What are the most common obsessions in youth?","a":"**Contamination**, then harm to self or others, symmetry and exactness, hoarding, religious or moral concerns."},
  {"id":"d2-oc03","tag":"OCD","q":"How do symptoms differ in tic-related OCD?","a":"More **counting, arranging and ordering**, less washing and cleaning."},
  {"id":"d2-oc04","tag":"OCD","q":"How are normal childhood rituals distinguished from OCD?","a":"Normal rituals **comfort**, do not impair and become less rigid by grade school; OCD rituals are driven by extreme fear, consume time and cause distress when interrupted."},
  {"id":"d2-oc05","tag":"OCD","q":"How do ASD repetitive behaviors differ from compulsions?","a":"They are **self-stimulating or comforting**, not responses to anxiety."},
  {"id":"d2-oc06","tag":"OCD","q":"In what share of youth is OCD a prodrome of psychosis?","a":"About **10%**."},
  {"id":"d2-oc07","tag":"OCD","q":"What predicted persistent OCD in the Maudsley follow-up?","a":"**Longer duration** of illness at first assessment (41% persisted at 9 years)."},
  {"id":"d2-oc08","tag":"OCD","q":"Which comorbidities predict poorer pediatric OCD outcome?","a":"**Tic disorders and ADHD**."},
  {"id":"d2-oc09","tag":"OCD","q":"What is PANDAS and its current status?","a":"Proposed post-streptococcal autoimmune OCD or tics; **controversial**, explaining at most a minority of cases."},
  {"id":"d2-oc10","tag":"OCD","q":"What is the prevalence of OCD in youth?","a":"Point about **0.5%**, lifetime **2–4%**, rising with age."},
  {"id":"d2-sc01","tag":"Schizophrenia","q":"Define early-onset and childhood-onset schizophrenia.","a":"Early-onset: before **18**; childhood-onset: before **13**."},
  {"id":"d2-sc02","tag":"Schizophrenia","q":"How do DSM-5 criteria differ for children with schizophrenia?","a":"**Failure to achieve** expected social and academic functioning can replace deterioration."},
  {"id":"d2-sc03","tag":"Schizophrenia","q":"Which hallucination types are unexpectedly common in childhood-onset schizophrenia?","a":"**Visual, tactile and olfactory**, besides auditory; visual ones link to earlier onset and lower IQ."},
  {"id":"d2-sc04","tag":"Schizophrenia","q":"What communication deficit marks children with schizophrenia?","a":"They fail to **repair** unclear speech (no repetition, revision or fillers), speak less and refer ambiguously."},
  {"id":"d2-sc05","tag":"Schizophrenia","q":"Are hallucinations alone enough to diagnose schizophrenia in a child?","a":"**No**: deterioration or failure to reach expected function is also required; stress-related hallucinations are self-limited."},
  {"id":"d2-sc06","tag":"Schizophrenia","q":"What proportion of children first diagnosed with schizophrenia later have bipolar disorder?","a":"About **one-third**."},
  {"id":"d2-sc07","tag":"Schizophrenia","q":"Which medical conditions can cause psychosis in youth?","a":"**Thyroid disease, systemic lupus, temporal lobe disease** (and drugs: amphetamines, LSD, PCP)."},
  {"id":"d2-sc08","tag":"Schizophrenia","q":"What predicts a poor course in childhood-onset schizophrenia?","a":"**Early, insidious onset**, family history, developmental delays, low IQ and premorbid function, long first episode, high expressed emotion."},
  {"id":"d2-sc09","tag":"Schizophrenia","q":"What is the prevalence of childhood-onset schizophrenia?","a":"Under **1 in 40,000** children; at least 50 times higher in adolescents; boys about 1.67:1."},
  {"id":"d2-sc10","tag":"APS","q":"What are the DSM-5 criteria for attenuated psychosis syndrome?","a":"Attenuated delusions, hallucinations or disorganized speech at least **weekly for a month**, new or worsening in the **past year**, impairing, with **insight** preserved (condition for further study)."},
  {"id":"d2-sc11","tag":"APS","q":"What are the conversion rates from prodromal symptoms to psychosis?","a":"**18%** at 6 months, 22% at 1 year, 29% at 2 years, **36%** at 3 years."},
  {"id":"d2-sc12","tag":"APS","q":"Why are psychotic-like symptoms weak predictors in youth?","a":"They are common: in **half** of depressed children and auditory hallucinations in **9–21%** of children."},
  {"id":"d2-su01","tag":"Substances","q":"How does DSM-5 classify adolescent substance problems?","a":"**Substance use disorder** (abuse and dependence merged), plus intoxication, withdrawal and substance-induced disorders."},
  {"id":"d2-su02","tag":"Substances","q":"What are nonspecific signs of adolescent substance use?","a":"**Falling grades**, vague physical complaints, family changes, **new peer group**, unexplained calls, poor hygiene: corroborate, as they overlap with depression and prodromes."},
  {"id":"d2-su03","tag":"Substances","q":"Describe the cannabis withdrawal timeline.","a":"Begins about **24 hours** after last use, peaks at **2–4 days**, diminishes after **2 weeks**."},
  {"id":"d2-su04","tag":"Substances","q":"Which club drugs are associated with date rape?","a":"**GHB, flunitrazepam (Rohypnol) and ketamine**: colorless, tasteless, odorless depressants."},
  {"id":"d2-su05","tag":"Substances","q":"What dangerous physical effect does MDMA cause?","a":"**Hyperthermia** (plus tachycardia, muscle spasm, dry mouth)."},
  {"id":"d2-su06","tag":"Substances","q":"Is alcohol usually a gateway to drug use in adolescents?","a":"**No**: in half of cases drinking followed drug use."},
  {"id":"d2-su07","tag":"Substances","q":"What share of teens with alcohol use disorders have another psychiatric disorder?","a":"More than **80%**, most often depressive, disruptive behavior and drug use disorders."}
]);
